-- TitanGlobal ERP: evaluaciones de proveedores (módulo 12, spec modulo12-evaluacion-proveedores-backend).
--
-- Una evaluación por proveedor y mes. El puntaje final y la calificación los calcula y guarda la aplicación;
-- las reglas CK_ repiten en la base lo que ya valida la API, como segunda defensa ante datos cargados por fuera.
-- Convención de nombres: CK_<Tabla>_<Regla>.

CREATE TABLE "EvaluacionesProveedor" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "ProveedorId" integer NOT NULL,
    "Periodo" character varying(7) NOT NULL,
    "PuntajeCumplimiento" integer NOT NULL,
    "PuntajeCalidad" integer NOT NULL,
    "PuntajePlazos" integer NOT NULL,
    "PuntajeFinal" numeric(5,2) NOT NULL,
    "Calificacion" character varying(20) NOT NULL,
    "Observaciones" character varying(500),
    "FechaRegistro" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_EvaluacionesProveedor" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_EvaluacionesProveedor_Proveedores_ProveedorId" FOREIGN KEY ("ProveedorId") REFERENCES "Proveedores" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_EvaluacionesProveedor_PeriodoFormato" CHECK ("Periodo" ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
    CONSTRAINT "CK_EvaluacionesProveedor_PuntajeCumplimiento" CHECK ("PuntajeCumplimiento" BETWEEN 0 AND 100),
    CONSTRAINT "CK_EvaluacionesProveedor_PuntajeCalidad" CHECK ("PuntajeCalidad" BETWEEN 0 AND 100),
    CONSTRAINT "CK_EvaluacionesProveedor_PuntajePlazos" CHECK ("PuntajePlazos" BETWEEN 0 AND 100),
    CONSTRAINT "CK_EvaluacionesProveedor_PuntajeFinal" CHECK ("PuntajeFinal" BETWEEN 0 AND 100),
    CONSTRAINT "CK_EvaluacionesProveedor_Calificacion" CHECK ("Calificacion" IN ('Excelente', 'Bueno', 'Regular', 'Deficiente'))
);
CREATE UNIQUE INDEX "IX_EvaluacionesProveedor_ProveedorId_Periodo" ON "EvaluacionesProveedor" ("ProveedorId", "Periodo");
